    out = [row[:] for row in grid[:3]]
    for r in range(3):
        for c in range(6):
            if out[r][c] != 0:
                continue
            # For blank canvas cells, colored mask indicates the replacement.
            for color, start in ((4, 3), (2, 6), (8, 9)):
                if grid[start+r][c] == color:
                    out[r][c] = color
                    break
    # A cell tagged 8 overrides the 2-mask, but only if originally blank.
    for r in range(3):
        for c in range(6):
